css:
@media print {
	@page { size: 80mm auto; margin: 0; }
}

.forkiva-receipt {
	font-family: 'Cairo', 'Segoe UI', Arial, sans-serif;
	font-size: 12px;
	color: #0f172a;
	width: 80mm;
	margin: 0 auto;
	padding: 3mm 4mm;
	box-sizing: border-box;
}

.fr-header {
	text-align: center;
	background: #0f172a;
	color: #ffffff;
	border-radius: 6px;
	padding: 4mm 2mm 3mm;
	margin-bottom: 3mm;
}
.fr-logo { max-width: 60px; max-height: 40px; margin-bottom: 1mm; background: #fff; border-radius: 4px; }
.fr-company { font-size: 15px; font-weight: 800; letter-spacing: .5px;color:#fff; }
.fr-meta { font-size: 10px; opacity: .8; margin-top: 1px; }
.fr-badge {
	display: inline-block;
	margin-top: 2mm;
	padding: 1mm 4mm;
	border: 1px solid #ffffff;
	border-radius: 20px;
	font-size: 9px;
	letter-spacing: 1.5px;
	font-weight: 700;
	color:#fff;
}

.fr-info table { width: 100%; border-collapse: collapse; margin-bottom: 3mm; }
.fr-info td { padding: .6mm 0; font-size: 11px; }
.fr-k { color: #64748b; width: 30%; }
.fr-v { font-weight: 600; }

.fr-items { margin-bottom: 3mm; }
.fr-items table { width: 100%; border-collapse: collapse; }
.fr-items th {
	text-align: left;
	font-size: 10px;
	color: #64748b;
	text-transform: uppercase;
	letter-spacing: .5px;
	border-bottom: 1.5px solid #0f172a;
	padding-bottom: 1mm;
}
.fr-items td { padding: 1.6mm 0; border-bottom: 1px dashed #e2e8f0; vertical-align: top; }
.fr-name { width: 58%; }
.fr-item-name { font-weight: 600; font-size: 11px; }
.fr-item-rate { font-size: 10px; color: #64748b; }
.fr-qty { width: 14%; text-align: center; }
.fr-amt { width: 28%; text-align: right; font-weight: 600; }

.fr-totals { margin-bottom: 3mm; }
.fr-row {
	display: flex;
	justify-content: space-between;
	padding: .8mm 0;
	font-size: 11px;
}
.fr-row.fr-grand {
	font-size: 14px;
	font-weight: 800;
	border-top: 1.5px solid #0f172a;
	margin-top: 1mm;
	padding-top: 1.5mm;
}
.fr-pay-method {
	margin-top: 1.5mm;
	text-align: center;
	font-weight: 700;
	font-size: 11px;
	border: 1px solid #0f172a;
	border-radius: 4px;
	padding: 1mm;
}

.fr-qr { text-align: center; margin: 3mm 0 2mm; }
.fr-qr img { width: 55px; height: 55px; }

.fr-footer { text-align: center; }
.fr-thanks { font-size: 12px; font-weight: 700; }
.fr-tag { font-size: 9px; color: #94a3b8; margin-top: .5mm; }

@media print {
	.print-heading, .page-head, .navbar, .sidebar-container { display: none !important; }
}

.fr-verify { margin-top: 1mm; font-size: 9px; }
.fr-verify a { color: #0f172a; word-break: break-all; }
